function buildDeck() {
  const deck = document.getElementById('deck');
  const prog = document.getElementById('progress');
  document.getElementById('tot').textContent = N;
  SLIDES.forEach((s,i)=>{
    const el = document.createElement('div');
    el.className = 'slide' + (i===0?' active':'');
    el.id = 'slide-'+i;
    el.innerHTML = buildSlideHTML(s,i);
    deck.appendChild(el);
    const dot = document.createElement('div');
    dot.className = 'pdot' + (i===0?' on':'');
    dot.onclick = ()=>goTo(i);
    prog.appendChild(dot);
  });
  renderContent();
}

function renderContent() {
  SLIDES.forEach((s,i)=>{
    const hl = document.getElementById('hl-'+i);
    const bd = document.getElementById('bd-'+i);
    const meta = document.getElementById('meta-'+i);
    if (hl && s.hl) hl.innerHTML = s.hl.replace(/\n/g,'<br>');
    if (bd && s.bd) bd.innerHTML = s.bd.replace(/\n/g,'<br>');
    if (meta && s.meta) meta.textContent = s.meta;
    if (s.stats) s.stats.forEach((st,si)=>{ const l = document.getElementById(`stat-lbl-${i}-${si}`); if (l) l.innerHTML = st.lbl.replace(/\n/g,'<br>'); });
    if (s.cards) s.cards.forEach((c,ci)=>{
      const st = document.getElementById(`cstep-${i}-${ci}`);
      const t = document.getElementById(`ctitle-${i}-${ci}`);
      const d = document.getElementById(`cdesc-${i}-${ci}`);
      if (st) st.textContent = c.step; if (t) t.textContent = c.hl; if (d) d.textContent = c.bd;
    });
    if (s.type === 'closing') {
      const banner = document.getElementById(`banner-${i}`);
      if (banner && s.banner) banner.innerHTML = s.banner.replace(/\n/g,'<br>');
      s.next.forEach((c,ci)=>{
        const t = document.getElementById(`next-t-${i}-${ci}`);
        const d = document.getElementById(`next-d-${i}-${ci}`);
        if (t) t.textContent = c.t; if (d) d.textContent = c.d;
      });
    }
    if (s.type === 'cmdcenter') {
      STAGES.forEach((st,si)=>{ const nn = document.getElementById(`cmd-nname-${si}`); if (nn) nn.innerHTML = st.t.replace(/\n/g,'<br>'); });
      if (cmdActiveIdx>=0) updateCmdContent();
    }
  });
