  if (s.type === 'statement') sel = `#slide-${slideIdx} .pt-item`;
  const cards = document.querySelectorAll(sel);
  if (!cards.length) return;
  if (cycleState[slideIdx] === undefined) cycleState[slideIdx] = 0;
  cards.forEach((c,i)=>c.classList.toggle('on', i===cycleState[slideIdx]));
  cycleIntervals[slideIdx] = setInterval(()=>{
    cards[cycleState[slideIdx]].classList.remove('on');
