function buildSlideHTML(s, i) {
  const ov = `<div class="s-ov"></div>`;

  if (s.type === 'cover') {
    return ov + `<div class="s-wrap centered">
      <img class="cover-logo" src="payme-logo.jpg" alt="PayMe">
      <div class="cover-tag">Strategic Partner Sales</div>
      <h1 class="cover-h">100,000 ₪ MRR נטו.<br><em>בארבעה חודשים.</em></h1>
      <div class="cover-line">לא ניתחתי שוק. בניתי תוכנית שותפויות שאפשר לפתוח בה את יום העבודה הראשון.</div>
      <div class="cover-meta"><span>הוגש על ידי</span><span class="cover-dot"></span><b>אליה בן כנען</b></div>
    </div>`;
  }

  if (s.type === 'process') {
    const cards = s.steps.map((c,ci)=>`
      <div class="proc-card" id="proc-card-${i}-${ci}"><div class="proc-num">${c.num}</div><h3>${c.h}</h3><p>${c.p}</p></div>`).join('');
    const band = s.band.map(e=>`<div class="proc-eng"><b>${e.b}</b><span>${e.s}</span></div>`).join('');
    const dir = s.dir ? `<div class="proc-dir"><span class="pd-tag">הכיוון</span>
      <div class="pd-eq"><b>100,000 ₪</b><span>נטו לחודש</span></div><i class="pd-op">÷</i>
      <div class="pd-eq"><b>100-150 ₪</b><span>ARPU נטו למשתמש</span></div><i class="pd-op">=</i>
      <div class="pd-eq pd-res"><b>~700-1,000</b><span>משתמשים לגייס</span></div></div>` : '';
    return ov + `<div class="s-wrap">
      <div class="label-sm">${s.kicker}</div><div class="rule"></div>
      <h1 class="h-lg" id="hl-${i}"></h1><p class="body-t" id="bd-${i}"></p>
      <div class="proc-grid">${cards}</div><div class="proc-band">${band}</div>${dir}
    </div>`;
  }

  if (s.type === 'split') {
    const cards = s.cards.map((c,ci)=>`
      <div class="fcard">
        <div class="fcard-step" id="cstep-${i}-${ci}"></div>
        <h3 id="ctitle-${i}-${ci}"></h3><p id="cdesc-${i}-${ci}"></p>
        ${c.mrr ? `<span class="mrr">${c.mrr}</span>` : ''}<div class="fcard-dot"></div>
      </div>`).join('');
    return ov + `<div class="s-wrap"><div class="split">
        <div class="split-l">${s.tag ? `<div class="label-sm">${s.tag}</div>` : ''}<div class="rule"></div>
          <h1 class="h-lg" id="hl-${i}"></h1><p class="body-t" id="bd-${i}"></p>
          ${s.foot ? `<div style="margin-top:22px;font-size:14px;font-weight:800;color:var(--accent)">${s.foot}</div>` : ''}
        </div>
        <div class="split-r${s.cards.length > 3 ? ' grid2' : ''}">${cards}</div>
      </div></div>`;
  }

  if (s.type === 'table') {
    const head = s.cols.map(c=>`<th>${c}</th>`).join('');
    const body = s.rows.map(r=>`<tr>${r.map(c=>`<td>${String(c).replace(/\n/g,'<br>')}</td>`).join('')}</tr>`).join('');
    return ov + `<div class="s-wrap centered">
      <div class="label-sm">${s.kicker||''}</div><div class="rule c"></div>
      <h1 class="h-xl" id="hl-${i}" style="font-size:clamp(34px,4.6vw,66px);margin-bottom:${s.sub?'8px':'0'}"></h1>
      ${s.sub ? `<p class="body-t" style="max-width:720px">${s.sub}</p>` : ''}
      <div class="tbl-wrap"><table class="ptable"><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>
      ${s.foot ? `<div class="tbl-foot">${s.foot.replace(/(~?[\d,]+(?:-[\d,]+)?\s*₪?)/,'<b>$1</b>')}</div>` : ''}
      ${s.src ? `<div class="tbl-src">${s.src}</div>` : ''}
    </div>`;
  }

  if (s.type === 'formula') {
    const terms = s.terms.map((t,ti)=>`
      <div class="fx-term"><div class="fx-term-t">${t.t}</div><div class="fx-term-ex">${t.ex}</div></div>
      ${ti < s.terms.length-1 ? '<div class="fx-op">×</div>' : ''}`).join('');
    const calc = s.terms.map(t=>t.ex).join(' × ') + ' = <b>' + s.result + '</b>';
    return ov + `<div class="s-wrap centered">
      <div class="label-sm">${s.kicker||''}</div><div class="rule c"></div>
