.pt-item p { font-size: 13.5px; line-height: 1.6; color: var(--gray); }

/* COMMAND CENTER */
.cmd-scan { position: absolute; inset: 0; z-index: 3; pointer-events: none; background: linear-gradient(180deg, transparent 0%, rgba(47,194,188,0.05) 50%, transparent 100%); opacity: 0; }
@keyframes scan { 0% { transform: translateY(-100%); opacity: 0;} 8% {opacity:1;} 92% {opacity:1;} 100% { transform: translateY(110%); opacity: 0;} }
.cmd-center { position: absolute; top: 78px; bottom: 70px; right: 0; left: 0; padding: 18px 72px 14px; display: flex; flex-direction: column; gap: 14px; z-index: 2; }
.cmd-bg-num { position: absolute; left: 56px; top: 20%; font-size: clamp(110px,18vw,280px); font-weight: 900; letter-spacing: -0.05em; color: rgba(47,194,188,0.07); line-height: 1; pointer-events: none; user-select: none; transition: opacity .3s; }
.cmd-header { display: flex; align-items: center; justify-content: space-between; flex-shrink: 0; }
.cmd-meta { font-size: 11px; font-weight: 800; letter-spacing: 0.1em; color: var(--accent); }
.cmd-selector { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1px; background: rgba(255,255,255,0.05); border-radius: 10px; overflow: hidden; border: 1px solid rgba(255,255,255,0.07); flex-shrink: 0; }
.cmd-node { background: var(--bg); padding: 17px 16px 15px; cursor: pointer; position: relative; overflow: hidden; transition: background .35s; }
.cmd-node.active { background: var(--card-hi); }
.cmd-node:hover:not(.active) { background: rgba(255,255,255,0.03); }
.cmd-node-num { font-size: 13px; font-weight: 900; color: var(--dim); margin-bottom: 6px; transition: color .35s; }
.cmd-node.active .cmd-node-num { color: var(--accent); }
.cmd-node-name { font-size: 13px; font-weight: 700; color: rgba(255,255,255,0.34); line-height: 1.35; transition: color .35s; }
.cmd-node.active .cmd-node-name { color: rgba(255,255,255,0.92); }
.cmd-node::before { content: ''; position: absolute; right: 0; top: 0; bottom: 0; width: 2px; background: var(--accent); opacity: 0; transition: opacity .35s; }
.cmd-node.active::before { opacity: 1; }
